    const toggle=document.createElement('button');toggle.type='button';toggle.className='btn btn-ghost road-demo-toggle';toggle.textContent='▶ Показать ситуацию на дороге';toggle.setAttribute('aria-expanded','false');
    const body=document.createElement('div');body.className='road-demo-body';body.hidden=true;
