    function frame(now){if(!playing)return;if(!wrap.isConnected||document.hidden||wrap.closest('.hide')||body.hidden){stop();return;}if(last)time=Math.min(duration,time+(now-last)/1000);last=now;draw();if(time>=duration)stop();else raf=requestAnimationFrame(frame);}
